package net.officefloor.hq.app.sheet;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class ValidateSheetId {
    public void validate(@PathVariable("sheetId") String sheetId, Out<SheetResponse> sheet)
            throws BadRequestException {
        String id = sheetId == null ? "" : sheetId.trim();
        if (id.isEmpty() || id.length() > 200) {
            throw new BadRequestException("Enter a sheet id");
        }
        sheet.set(new SheetResponse(id));
    }
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Val;

public class EnsureSheet {
    public void ensure(@Val SheetResponse sheet, SheetRepository repository) {
        repository.ensure(sheet.id());
    }
}
package net.officefloor.hq.app.access;

/** A role assigned to a user name on a sheet: clerk (any name without one) or steward. */
public record Role(String sheetId, String user, String role) {

    public static final String CLERK = "clerk";

    public static final String STEWARD = "steward";
}
package net.officefloor.hq.app.access;

import java.util.Set;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A role assignment's fields: a user name (no spaces) and a role, clerk or steward. */
public class ValidateRole {

    private static final Set<String> ROLES = Set.of(Role.CLERK, Role.STEWARD);

    public void validate(@RequestBody RoleRequest request, Out<RoleInput> role, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String user = request == null || request.user() == null ? "" : request.user().trim();
        String asked = request == null || request.role() == null ? "" : request.role().trim();
        if (user.isEmpty()) {
            throw new BadRequestException("Enter a user name");
        }
        if (user.length() > 200 || user.chars().anyMatch(Character::isWhitespace)) {
            throw new BadRequestException("A user name is one word");
        }
        if (!ROLES.contains(asked)) {
            throw new BadRequestException("A role is clerk or steward");
        }
        role.set(new RoleInput(user, asked));
        changedBy.set(by);
    }
}
